; @mideas:block id=runtime.screens.load_screen_music_runtime_screen_usic_runtime.loader kind=routine owner=screens roots=load_screen_music_runtime_screen_usic_runtime
load_screen_music_runtime_screen_usic_runtime:
    ; Load Music Runtime Screen screen (fast direct port access)
    ld a, 0
    ld (current_screen_engine), a
    ld a, #FF
    ld (autocontrol_screen_id), a
    ; Set VDP colors FIRST (before loading screen data)
    ld a, 1           ; Background color
    ld b, 1       ; Border color
    call set_screen_colors
    ; Initialize character 0 (empty cells) with background color
    ld a, 1           ; Background color for char 0
    call init_char0_color
    ; Build mutable runtime screen background maps in RAM
    ld hl, SCREEN_MUSIC_RUNTIME_SCREEN_0_LAYOUT
    ld de, runtime_background_layout
    ld bc, RUNTIME_SCREEN_MAP_SIZE
    ldir
    ld hl, SCREEN_MUSIC_RUNTIME_SCREEN_0_LAYOUT
    ld de, runtime_screen_layout
    ld bc, RUNTIME_SCREEN_MAP_SIZE
    ldir
    ld hl, SCREEN_MUSIC_RUNTIME_SCREEN_0_EFFECTS_LAYOUT
    ld de, runtime_effects_layout
    ld bc, RUNTIME_SCREEN_MAP_SIZE
    ldir

    ld hl, BEHAVIOR_MUSIC_RUNTIME_SCREEN_0_DATA
    ld de, runtime_behavior_map
    ld bc, RUNTIME_SCREEN_MAP_SIZE
    ldir

    ld hl, SCREEN_MUSIC_RUNTIME_SCREEN_0_INTERACTION_TYPE_MAP
    ld de, runtime_interaction_type_map
    ld bc, RUNTIME_SCREEN_MAP_SIZE
    ldir

    ld hl, SCREEN_MUSIC_RUNTIME_SCREEN_0_INTERACTION_VALUE_MAP
    ld de, runtime_interaction_value_map
    ld bc, RUNTIME_SCREEN_MAP_SIZE
    ldir

    ld hl, SCREEN_MUSIC_RUNTIME_SCREEN_0_INTERACTION_TARGET_MAP
    ld de, runtime_interaction_target_map
    ld bc, RUNTIME_SCREEN_MAP_SIZE
    ldir

    ld a, 0
    ld (current_effect_zone_count), a
    or a
    jr z, .load_music_runtime_screen_usic_runtime_zones_done
    ld hl, SCREEN_MUSIC_RUNTIME_SCREEN_0_EFFECT_ZONE_TABLE
    ld de, runtime_effect_zone_table
    ld bc, 0
    ldir
.load_music_runtime_screen_usic_runtime_zones_done:
    ; Transition->WorldLink reveal mode prepares runtime_screen_layout first,
    ; then GameFlow reveals it by raster after the world loader returns.
    ld a, (gameflow_reveal_world_after_load)
    or a
    jr nz, load_screen_music_runtime_screen_usic_runtime_skip_vram_copy
    ; Now load screen layout (full 32x24) from runtime RAM buffer
    ld hl, runtime_screen_layout
    ld de, NAMETBL
    ld bc, RUNTIME_SCREEN_MAP_SIZE
    call FAST_LDIRVM           ; Fast VRAM write (direct port access)
load_screen_music_runtime_screen_usic_runtime_skip_vram_copy:
    ld a, 0
    ld (current_screen_anim_group_count), a
    ld a, 0
    ld (current_screen_entity_count), a
    ld a, 1
    ld (current_screen_sprite_pattern_slots), a
    ld a, SCREEN_MUSIC_RUNTIME_SCREEN_0_SUMMARY_FLAGS
    ld (current_screen_summary_flags), a
    ld a, SCREEN_MUSIC_RUNTIME_SCREEN_0_BOSS_COUNT
    ld (current_screen_boss_count), a
    or a
    jp z, load_music_runtime_screen_usic_runtime_boss_done
    ld hl, SCREEN_MUSIC_RUNTIME_SCREEN_0_BOSS_TABLE
    ld de, current_screen_boss_entry
    ld bc, BOSS_PLACEMENT_ENTRY_SIZE
    ldir
    ld hl, current_screen_boss_entry
    ld (current_screen_boss_table), hl
    ld a, #FF
    ld (current_screen_boss_table_bank), a
load_music_runtime_screen_usic_runtime_boss_done:


    ; Initialize collision system pointers for this screen
    ld hl, runtime_screen_layout
    ld (current_screen_layout), hl
    ld a, #FF
    ld (current_screen_layout_bank), a
    ld hl, runtime_behavior_map
    ld (current_behavior_map), hl
    ld a, #FF
    ld (current_behavior_map_bank), a
    ld a, l
    ld (behavior_cache_map_l), a
    ld a, h
    ld (behavior_cache_map_h), a
    ld a, #FF
    ld (behavior_cache_row), a
    xor a
    ld (secret_zone_active), a
    ld (secret_zone_rect_x), a
    ld (secret_zone_rect_y), a
    ld (secret_zone_rect_w), a
    ld (secret_zone_rect_h), a
    ld hl, entity_button_contact_active
    ld de, entity_button_contact_active + 1
    ld bc, 31
    ld (hl), a
    ldir
    ret
; @mideas:endblock id=runtime.screens.load_screen_music_runtime_screen_usic_runtime.loader


