; Node: Start - "gf_start_music_ia"
gameflow_node_gf_start_music_ia:
    db NODE_TYPE_START
    dw gameflow_node_gf_start_music_ia_data
    dw gameflow_node_gf_start_music_ia_conn

gameflow_node_gf_start_music_ia_data:
    dw gameflow_node_gf_start_music_ia_init    ; Initialization routine address
    db ((gameflow_node_gf_start_music_ia_init - #4000) / #2000)    ; Initialization routine bank

gameflow_node_gf_start_music_ia_conn:
    db CONNECTION_DEFAULT
    dw gameflow_node_gf_music_glass_runner
    db CONNECTION_END

; ------------------------------------------------------------------
; gameflow_node_gf_start_music_ia_init
; Initialization routine for Start node
; Initializes global variables and MSX systems
; ------------------------------------------------------------------
gameflow_node_gf_start_music_ia_init:
    ; === Core Game Systems Initialization (ALWAYS required) ===
    call init_game_systems

    ret

; Node: Music - "gf_music_glass_runner"
gameflow_node_gf_music_glass_runner:
    db NODE_TYPE_MUSIC
    dw gameflow_node_gf_music_glass_runner_data
    dw gameflow_node_gf_music_glass_runner_conn

gameflow_node_gf_music_glass_runner_data:
    db 1, 0, 1    ; command, track index, loop flag

gameflow_node_gf_music_glass_runner_conn:
    db CONNECTION_DEFAULT
    dw gameflow_node_gf_end_music_ia
    db CONNECTION_END

; Node: End - "gf_end_music_ia"
gameflow_node_gf_end_music_ia:
    db NODE_TYPE_END
    dw gameflow_no_data
    dw gameflow_node_gf_end_music_ia_conn

gameflow_node_gf_end_music_ia_conn:
    db CONNECTION_DEFAULT
    dw 0
    db CONNECTION_END


